def loanAmount = payload.loanAmount;
def riskGroup;
if (loanAmount > 100000) {
	riskGroup = 'Red';
} else {
	riskGroup = 'Green';
}
payload.riskGroup = riskGroup;

processContext.persist(payload);

payload.applicationStatus = 'REJECTED';
payload.rejectionReason = 'Application is ineligible based on risk assessment (Red group).';

processContext.persist(payload);

def spOutcome = payload.spTermsOutcome;
def accepted = (spOutcome == 'ACCEPTED');
payload.termsAccepted = accepted;

processContext.persist(payload);

payload.applicationStatus = 'REJECTED';
payload.fundsAllocated = false;
payload.rejectionReason = 'Applicant rejected terms and conditions.';

processContext.persist(payload);

def applicantName = payload.applicantName;
def applicantEmail = payload.applicantEmail;
def loanAmount = payload.loanAmount;
def sdf = new java.text.SimpleDateFormat("yyyy-MM-dd'T'HH:mm:ss");
def generatedDate = sdf.format(new java.util.Date());
def termsDocument = [
	applicantName: applicantName,
	applicantEmail: applicantEmail,
	loanAmount: loanAmount,
	termsContent: 'Standard loan terms and conditions for the requested loan amount of ' + loanAmount + '.',
	generatedDate: generatedDate
];
payload.termsDocument = termsDocument;
payload.termsSentToApplicant = true;

processContext.persist(payload);

def decision = taskCompletionPayload.reasonCode;
def message = 'Term decision: ' + decision;
payload.termsDecision = message;

processContext.persist(payload);

def applicantName = payload.applicantName;
def loanAmount = payload.loanAmount;

def notificationMessage = "URGENT: The credit check for applicant '" + applicantName + "' (loan amount: " + loanAmount + ") has exceeded the 10-day threshold. Please accelerate the decision on this application.";

payload.ceoNotificationSent = true;
payload.ceoNotificationMessage = notificationMessage;

def sdf = new java.text.SimpleDateFormat("yyyy-MM-dd'T'HH:mm:ss");
def timestamp = sdf.format(new Date());
payload.ceoNotificationTimestamp = timestamp;

processContext.persist(payload);

payload.applicationStatus = 'CANCELLED';
def cancellationReason = 'Secondary loan manager did not complete credit check review within 30 days';
payload.cancellationReason = cancellationReason;
def now = new Date();
def sdf = new java.text.SimpleDateFormat("yyyy-MM-dd'T'HH:mm:ss");
def formattedDate = sdf.format(now);
payload.cancellationDate = formattedDate;

processContext.persist(payload);

def status = payload.applicationStatus;
def reason = payload.cancellationReason;
def cancelDate = payload.cancellationDate;
def body = [applicationStatus: status, cancellationReason: reason, cancellationDate: cancelDate];
def result = new groovy.json.JsonBuilder(body).toString();
payload.auditCancelRequestBody = result;

processContext.persist(payload);

def statusCode = response.statusLine.statusCode;
if (statusCode < 200 || statusCode >= 300) {
	processContext.throwBpmnError('Audit cancel service returned status code: ' + statusCode);
}
